import {createRoot} from 'react-dom/client';
import {ConfigProvider,App as AntApp,Button,Input,Form,Select,Modal,Tag,Spin,Empty,Alert,Dropdown,Tooltip,Table,Switch,Descriptions,Collapse,DatePicker} from 'antd';
import zhCN from 'antd/locale/zh_CN';
import {HomeFilled,BellOutlined,ArrowRightOutlined,ArrowUpOutlined,AppstoreOutlined,MessageOutlined,EditOutlined,FolderOpenOutlined,BookOutlined,ScheduleOutlined,SettingOutlined,PlusOutlined,SearchOutlined,LogoutOutlined,UserOutlined,CheckCircleOutlined,FileTextOutlined,RobotOutlined,ReloadOutlined,SendOutlined,LinkOutlined,DownloadOutlined,PictureOutlined,ShopOutlined,ThunderboltOutlined,CopyOutlined,MoreOutlined,MenuOutlined,SafetyCertificateOutlined} from '@ant-design/icons';
import ReactMarkdown from 'react-markdown';
import {api,Data,time,statuses,requestId} from './api';
import {useData,watchJob} from './lifecycle';
import {Home} from './Home';
import {CustomerNeeds,NEED_FIELDS,knownNeed} from './CustomerNeeds';
