const {TextArea}=Input;
const PLATFORMS=['小红书','公众号','朋友圈','海报'];
type Context={modal:ReturnType<typeof AntApp.useApp>['modal'];user:Data;products:Data[];navigate:(view:string,id?:string)=>void;action:(fn:()=>Promise<any>)=>Promise<any>;watch:(id:string,onDone?:(job:Data)=>void,onSettled?:(job:Data)=>void)=>void};

function Markdown({text}:{text:string}){return <div className="prose"><ReactMarkdown>{text||''}</ReactMarkdown></div>}
function Badge({status}:{status:string}){return <Tag color={['passed','manual_passed','completed'].includes(status)?'green':status==='failed'?'red':status==='running'?'processing':'default'}>{statuses[status]||status}</Tag>}
function jobLabel(job:Data){
 const names:Data={analysis:'整理客户需求',suggest:'准备回复建议',generate:'生成图文',verify:'检查内容',repair:'调整并检查内容',image:'生成背景',import:'更新产品资料'};
 if(job.status==='failed')return '暂时未能完成，请稍后重试。';
 if(job.status==='waiting_remote')return '背景仍在生成，可以稍后继续查看。';
 if(job.status==='needs_input')return '请补充创作信息。';
 if(job.status==='completed')return '已完成';
 if(job.status==='cancelled')return '已停止';
 return (job.status==='queued'?'等待':'正在')+(names[job.kind]||'处理');
}
function Loading({error=''}:{error?:string}){return error?<Alert type="error" message={error}/>:<div className="loading"><Spin/><span>正在载入工作空间</span></div>}
function Heading({eyebrow,title,description,extra}:{eyebrow:string;title:string;description:string;extra?:React.ReactNode}){return <div className="page-heading"><div><h1>{title}</h1>{description&&<p>{description}</p>}</div>{extra}</div>}
function ProductCard({p,onClick}:{p:Data;onClick:()=>void}){return <button className="product-card" onClick={onClick}><div className="product-photo"><img src={p.cover} alt={p.name} loading="lazy"/></div><div className="product-copy"><small>HUAWEI PC</small><h3>{p.name.replace('HUAWEI ','')}</h3><span>查看产品资料 <ArrowRightOutlined/></span></div></button>}

function Root(){
 const {message,modal}=AntApp.useApp();
 const [me,setMe]=useState<Data|null>(null),[ready,setReady]=useState(false),[view,setView]=useState(location.pathname.startsWith('/staff')?'dashboard':'customer'),[selected,setSelected]=useState(''),[auth,setAuth]=useState(false),[authMode,setAuthMode]=useState('login'),[mobileMenu,setMobileMenu]=useState(false);
 const [job,setJob]=useState<Data|null>(null);const sources=useRef<Set<()=>void>>(new Set());
 const products=useData('/products'),store=useData('/store');
 const refreshMe=useCallback(async()=>{const data=await api('/me');setMe(data.user);setReady(true);},[]);
 useEffect(()=>{void refreshMe();return()=>sources.current.forEach(stop=>stop());},[refreshMe]);
 const action=async(fn:()=>Promise<any>)=>{try{return await fn();}catch(e){message.error((e as Error).message);return null;}};
 const navigate=(v:string,id='')=>{setView(v);setSelected(id);setMobileMenu(false);history.replaceState({},'',v==='customer'?'/':'/staff');};
 const watch=(id:string,onDone?:(j:Data)=>void,onSettled?:(j:Data)=>void)=>{
  const stop=watchJob(id,next=>{setJob(next);if(!['running','queued'].includes(next.status))onSettled?.(next);if(next.status==='failed')message.error('暂时未能完成，请稍后重试。');if(next.status==='needs_input')message.warning('请从通知中打开任务，补充创作信息');},next=>{message.success(next.kind==='image'?'背景图片已生成':'任务已完成');onDone?.(next);});sources.current.add(stop);
 };
 const ctx:Context={modal,user:me||{},products:products.data||[],navigate,action,watch};
 const staff=me&&['staff','admin'].includes(me.role);
 const logout=()=>action(async()=>{await api('/auth/logout','POST');sources.current.forEach(stop=>stop());sources.current.clear();setJob(null);setMe(null);navigate('customer');});
 const authSubmit=async(values:Data)=>action(async()=>{const u=await api('/auth/'+authMode,'POST',values);setMe(u);setAuth(false);navigate(['staff','admin'].includes(u.role)?'dashboard':'customer');});
 if(!ready)return <Loading/>;
 const activeNav=['chat','followups'].includes(view)?'chat':['works','create'].includes(view)?'works':view;
 const nav=[['dashboard',<HomeFilled/>,'首页'],['chat',<MessageOutlined/>,'客户接待'],['works',<EditOutlined/>,'营销内容'],['products',<FolderOpenOutlined/>,'产品资料']];
 return <>
  {staff&&view!=='customer'?<div className="shell">
   <aside className={'sidebar '+(mobileMenu?'visible':'')}><a className="brand" href="/staff"><div className="brand-symbol">知</div><div>知客<span>门店增长工作台</span></div></a><nav aria-label="主导航">{nav.map(([key,icon,label])=><button key={String(key)} aria-current={activeNav===key?'page':undefined} className={activeNav===key?'active':''} onClick={()=>navigate(String(key))}>{icon}<span>{label}</span>{activeNav===key&&<i/>}</button>)}</nav><div className="profile"><div className="avatar">{me.display_name[0]}</div><div><strong>{me.display_name}</strong><small>{me.role==='admin'?'门店管理员':'门店顾问'}</small></div><Dropdown trigger={['click']} menu={{items:[...(me.role==='admin'?[{key:'settings',label:'管理设置',icon:<SettingOutlined/>}]:[]),{key:'logout',label:'退出登录',icon:<LogoutOutlined/>}],onClick:({key})=>key==='settings'?navigate('settings'):logout()}}><Button type="text" aria-label="账号与设置" icon={<SettingOutlined/>}/></Dropdown></div></aside>
   <div className="main-shell"><header className="topbar"><div><Button className="menu-trigger" type="text" icon={<MenuOutlined/>} onClick={()=>setMobileMenu(!mobileMenu)}/><ShopOutlined/><span>{store.data?.name||'门店工作台'}</span></div><div><Notifications navigate={navigate}/><Button onClick={()=>navigate('customer')} icon={<LinkOutlined/>}>客户咨询入口</Button></div></header><main className={'page '+(view==='chat'?'chat-page':view==='dashboard'?'home-container':'')}>
    {['chat','followups'].includes(view)&&<div className="section-navigation" aria-label="客户管理"><button className={view==='chat'?'selected':''} onClick={()=>navigate('chat')}>接待会话</button><button className={view==='followups'?'selected':''} onClick={()=>navigate('followups')}>跟进计划</button></div>}
    {['works','create'].includes(view)&&<div className="section-navigation" aria-label="营销内容"><button className={view==='works'?'selected':''} onClick={()=>navigate('works')}>全部作品</button><button className={view==='create'?'selected':''} onClick={()=>navigate('create')}>新建内容</button></div>}
    {view==='dashboard'&&<Dashboard {...ctx}/>}{view==='chat'&&<Chat {...ctx} selected={selected} onSelect={setSelected}/>}{view==='create'&&<Creator {...ctx} initial={selected}/>}{view==='works'&&<Works {...ctx} selected={selected}/>}{view==='products'&&<Products {...ctx}/>}{view==='followups'&&<Followups {...ctx} selected={selected}/>}{view==='settings'&&<Settings {...ctx}/>}{view==='tasks'&&<Tasks {...ctx}/>}
   </main></div>
  </div>:<Customer {...ctx} user={me} store={store.data} openAuth={(mode)=>{setAuthMode(mode);setAuth(true);}} onGuest={refreshMe} logout={logout}/>}
  <Modal open={auth} onCancel={()=>setAuth(false)} footer={null} title={authMode==='login'?'欢迎回来':'创建客户账号'} destroyOnClose><p className="muted">{authMode==='login'?'客户和客服均可在这里登录。':'注册后，可跨设备查看自己的咨询记录。'}</p><Form layout="vertical" onFinish={authSubmit}><Form.Item name="username" label="用户名" rules={[{required:true,pattern:/^[A-Za-z0-9_\-]{3,40}$/,message:'3～40位字母、数字、下划线'}]}><Input autoComplete="username"/></Form.Item>{authMode==='register'&&<Form.Item name="display_name" label="昵称"><Input maxLength={40}/></Form.Item>}<Form.Item name="password" label="密码" rules={[{required:true,min:10,message:'密码至少10位'}]}><Input.Password autoComplete={authMode==='login'?'current-password':'new-password'}/></Form.Item><Button block type="primary" htmlType="submit">{authMode==='login'?'登录':'注册并保留当前咨询'}</Button></Form><Button block type="link" onClick={()=>setAuthMode(authMode==='login'?'register':'login')}>{authMode==='login'?'还没有账号？注册':'已有账号？登录'}</Button></Modal>
  {staff&&job&&<div className="job-notice"><div className="job-notice-icon">{['running','queued'].includes(job.status)?<Spin size="small"/>:<RobotOutlined/>}</div><div><b>{jobLabel(job)}</b></div>{job.result?.work_id&&<Button size="small" onClick={()=>navigate('works',job.result.work_id)}>查看作品</Button>}{['failed','waiting_remote'].includes(job.status)&&<Button size="small" onClick={()=>action(async()=>{const r=await api('/jobs/'+job.id+'/retry','POST');watch(r.job_id);})}>重试</Button>}<Button type="text" size="small" aria-label="关闭任务提示" onClick={()=>setJob(null)}>×</Button></div>}
 </>;
}

function Notifications({navigate}:{navigate:Context['navigate']}){
 const {data}=useData('/jobs',15000);
 const attention=data?.some((job:Data)=>['queued','running','needs_input','waiting_remote','failed'].includes(job.status));
 return <Button className="notifications-button" type="text" aria-label="通知与进度" title="通知与进度" onClick={()=>navigate('tasks')}><BellOutlined/>{attention&&<span className="notification-dot" aria-hidden="true"/>}</Button>;
}

function Dashboard(ctx:Context){
 const summary=useData('/dashboard',8000),followups=useData('/followups',10000),works=useData('/works',10000);
 if(!summary.data)return <Loading error={summary.error}/>;
 return <Home summary={summary.data} productsCount={ctx.products.length} followups={followups.data} works={works.data} followupsError={followups.error} worksError={works.error} navigate={ctx.navigate}/>;
}

function Customer({user,store,openAuth,onGuest,logout,...ctx}:Omit<Context,'user'>&{user:Data|null;store:Data|null;openAuth:(m:string)=>void;onGuest:()=>Promise<void>;logout:()=>void}){
 const [cid,setCid]=useState(''),[nickname,setNickname]=useState(''),[busy,setBusy]=useState(false),[historyPage,setHistoryPage]=useState(1);
 const convs=useData(user?'/conversations':'/products',user?10000:0);
 const start=async()=>{setBusy(true);await ctx.action(async()=>{if(!user){await api('/auth/guest','POST',{name:nickname.trim()||'访客'});await onGuest();}const c=await api('/conversations','POST');setCid(c.id);await convs.refresh();});setBusy(false);};
 const isStaff=user&&['staff','admin'].includes(user.role);
 const historyCount=convs.data?.length||0,historyPages=Math.max(1,Math.ceil(historyCount/3)),currentHistoryPage=Math.min(historyPage,historyPages);
 const visibleConversations=(convs.data||[]).slice((currentHistoryPage-1)*3,currentHistoryPage*3);
 return <div className="customer-shell"><header className="customer-header"><a className="brand" href="/"><div className="brand-symbol">知</div><div>知客<span>让选择，更有依据</span></div></a><div>{isStaff?<Button onClick={()=>ctx.navigate('dashboard')}>返回工作台</Button>:user?<><span className="muted">{user.display_name}</span>{user.role==='guest'&&<Button onClick={()=>openAuth('register')}>注册保存咨询</Button>}<Button type="text" onClick={logout}>退出</Button></>:<><Button type="text" onClick={()=>openAuth('login')}>登录</Button><Button onClick={()=>openAuth('register')}>注册</Button></>}</div></header>
 {cid&&user?<div className="customer-chat-layout"><Button type="text" onClick={()=>setCid('')}>← 返回咨询首页</Button><ChatWindow key={cid} {...ctx} user={user} cid={cid} customer/></div>:<>
 <section className="customer-hero"><div><div className="eyebrow">YOUR NEXT PC, YOUR WAY</div><h1>适合你的电脑，<br/>从聊聊需求开始。</h1><p>{store?.welcome||'把需求告诉我们，让每一次选择都有依据。'}<br/>学习、办公或创作，门店顾问和你一起找到答案。</p>{!isStaff&&<div className="start-consult">{!user&&<Input aria-label="咨询昵称" placeholder="怎么称呼你？（选填）" value={nickname} onChange={e=>setNickname(e.target.value)} maxLength={30}/>}<Button type="primary" size="large" loading={busy} onClick={start}>开始咨询 <ArrowRightOutlined/></Button></div>}<div className="customer-perks"><span><CheckCircleOutlined/>真人顾问接待</span><span><BookOutlined/>产品资料有据可查</span><span><SafetyCertificateOutlined/>按需推荐</span></div></div><div className="customer-hero-product">{ctx.products[0]&&<img src={ctx.products.find(p=>p.name.includes('14（'))?.cover||ctx.products[0].cover} alt="华为 PC 产品展示"/>}<span className="product-corner">HUAWEI PC<br/><b>探索更多可能</b></span></div></section>
 {user&&!isStaff&&<section className="customer-section customer-consultations" aria-label="我的咨询"><div className="section-title"><h2>我的咨询</h2><span className="muted">仅本人可见</span></div>{historyCount?<><div className="customer-history-list">{visibleConversations.map((c:Data)=><button className="conversation-row" key={c.id} onClick={()=>setCid(c.id)}><MessageOutlined/><div><b>{c.status==='closed'?'已结束的咨询':'与门店顾问的对话'}</b><p>{c.last_message}</p></div><small>{time(c.updated_at)}</small><ArrowRightOutlined/></button>)}</div>{historyPages>1&&<nav className="customer-history-pagination" aria-label="咨询记录翻页"><span>共 {historyCount} 条</span><Button size="small" disabled={currentHistoryPage===1} onClick={()=>setHistoryPage(currentHistoryPage-1)}>上一页</Button><span aria-live="polite">{currentHistoryPage} / {historyPages}</span><Button size="small" disabled={currentHistoryPage===historyPages} onClick={()=>setHistoryPage(currentHistoryPage+1)}>下一页</Button></nav>}</>:<p className="muted">还没有咨询记录，随时和我们聊聊。</p>}</section>}
 <section className="customer-section"><div className="section-title"><h2>认识你的下一台电脑</h2><span className="muted">具体配置以对应销售版本为准</span></div><div className="product-grid">{ctx.products.slice(0,4).map(p=><ProductCard key={p.id} p={p} onClick={()=>{if(isStaff)ctx.navigate('products');else void start();}}/>)}</div></section><div className="customer-bottom"><ShopOutlined/><b>{store?.name}</b><span>接待时间 {store?.hours}（北京时间）</span><p>产品图片来自本地资料库 · AI仅辅助顾问 · 价格与权益需当日确认</p></div></>}
 </div>;
}

function Chat(ctx:Context&{selected:string;onSelect:(id:string)=>void}){
 const convs=useData('/conversations',4000);const [query,setQuery]=useState(''),[filter,setFilter]=useState('all');
 useEffect(()=>{if(!ctx.selected&&convs.data?.length)ctx.onSelect(convs.data[0].id);},[convs.data,ctx.selected]);
 return <><div className="chat-title"><div><h1>客户接待</h1></div></div><div className="chat-workspace"><aside className="conversation-list"><div className="conversation-tools"><Input placeholder="搜索客户或消息" prefix={<SearchOutlined/>} value={query} onChange={e=>setQuery(e.target.value)}/><div className="filter-tabs">{[['all','全部'],['waiting','待接待'],['active','接待中']].map(([k,v])=><button key={k} className={filter===k?'active':''} onClick={()=>setFilter(k)}>{v}</button>)}</div></div>{convs.error&&<Alert message={convs.error} type="error"/>}{convs.data?.filter((c:Data)=>(filter==='all'||c.status===filter)&&(c.customer_name+c.last_message).includes(query)).map((c:Data)=><button key={c.id} onClick={()=>ctx.onSelect(c.id)} className={'conversation-item '+(ctx.selected===c.id?'selected':'')}><span className="avatar pastel">{c.customer_name[0]}</span><div><div><b>{c.customer_name}</b><small>{time(c.updated_at)}</small></div><p>{c.last_message}</p><span className="conversation-state">{c.status==='waiting'?'待接待':c.status==='closed'?'已结束':c.owner_name||'接待中'}{c.unread>0&&<i>{c.unread}</i>}</span></div></button>)}{convs.data?.length===0&&<Empty description="等待客户开始咨询" image={Empty.PRESENTED_IMAGE_SIMPLE}/>}</aside>{ctx.selected?<ChatWindow key={ctx.selected} {...ctx} cid={ctx.selected}/>:<div className="chat-empty"><MessageOutlined/><h2>选择客户开始接待</h2><p>从左侧选择会话，或打开客户咨询入口。</p></div>}</div></>;
}

function ChatWindow(ctx:Context&{cid:string;customer?:boolean}){
 const detail=useData('/conversations/'+ctx.cid,2500);const [text,setText]=useState(''),[analyzing,setAnalyzing]=useState(false),[sending,setSending]=useState(false),[suggestion,setSuggestion]=useState<Data|null>(null),[product,setProduct]=useState(''),[edit,setEdit]=useState<Data|null>(null);const end=useRef<HTMLDivElement>(null);const pendingSend=useRef<{client_id:string;content:string;product_id:string}|null>(null);
 useEffect(()=>{let stopped=false;let ws:WebSocket;let retry:ReturnType<typeof setTimeout>;const connect=()=>{if(stopped)return;ws=new WebSocket(`${location.protocol==='https:'?'wss:':'ws:'}//${location.host}/api/ws/${ctx.cid}`);ws.onopen=()=>void detail.refresh();ws.onmessage=e=>{if(JSON.parse(e.data).event==='updated')void detail.refresh();};ws.onclose=()=>{if(!stopped)retry=setTimeout(connect,2000);};};connect();const timer=setInterval(()=>{if(ws?.readyState===1)ws.send('ping');},20000);return()=>{stopped=true;clearTimeout(retry);clearInterval(timer);ws?.close();};},[ctx.cid]);
 useEffect(()=>{end.current?.scrollIntoView({behavior:'smooth',block:'nearest'});},[detail.data?.messages?.length]);
 const send=async(product_id='')=>{if(!text.trim()&&!product_id)return;setSending(true);await ctx.action(async()=>{if(!pendingSend.current||pendingSend.current.content!==text||pendingSend.current.product_id!==product_id)pendingSend.current={client_id:requestId(),content:text,product_id};await api('/conversations/'+ctx.cid+'/messages','POST',{...pendingSend.current,product_id});pendingSend.current=null;setText('');await detail.refresh();});setSending(false);};
 const c=detail.data;if(!c)return <Loading error={detail.error}/>;
 const owned=c.owner_id===ctx.user.id;const analysis=c.analysis||{};
 const ai=async(kind:string)=>{if(kind==='analysis'&&analyzing)return;if(kind==='analysis')setAnalyzing(true);const j=await ctx.action(()=>api(`/conversations/${ctx.cid}/ai/${kind}`,'POST',{product_id:product}));if(!j){setAnalyzing(false);return;}ctx.watch(j.job_id,job=>{if(kind==='suggest')setSuggestion(job.result);void detail.refresh();},()=>{if(kind==='analysis')setAnalyzing(false);void detail.refresh();});};
 const brief=()=>{const selectedProduct=product||'';ctx.navigate('create',JSON.stringify({product_id:selectedProduct,audience:knownNeed(analysis.user?.value),scene:[knownNeed(analysis.tasks?.value),knownNeed(analysis.software?.value)&&'需使用：'+knownNeed(analysis.software?.value)].filter(Boolean).join('；'),emphasis:knownNeed(analysis.concerns?.value)}));};
 return <><div className={ctx.customer?'customer-consultation-workspace':'staff-chat-content'}><section className={'chat-center '+(ctx.customer?'customer-chat':'')}><div className="chat-contact"><span className="avatar">{ctx.customer?<ShopOutlined/>:c.customer_name[0]}</span><div><b>{ctx.customer?'门店选购顾问':c.customer_name}</b><small>{c.status==='closed'?'会话已结束':c.owner_id?'顾问接待中':'等待顾问接待'} · {ctx.customer?'回复由真人顾问确认':c.stage}</small></div>{!ctx.customer&&<div className="contact-actions">{!c.owner_id?<Button type="primary" onClick={()=>ctx.action(async()=>{await api(`/conversations/${c.id}/claim`,'POST');await detail.refresh();})}>认领会话</Button>:!owned?<Button onClick={()=>ctx.modal.confirm({title:'接管此会话？',content:'接管后由你负责回复客户。',onOk:()=>ctx.action(async()=>{await api(`/conversations/${c.id}/takeover`,'POST',{expected_owner:c.owner_id});await detail.refresh();})})}>接管会话</Button>:<Button onClick={()=>ctx.action(async()=>{await api('/conversations/'+c.id,'PATCH',{status:c.status==='closed'?'active':'closed'});await detail.refresh();})}>{c.status==='closed'?'重新打开':'结束接待'}</Button>}</div>}{ctx.customer&&c.status==='closed'&&<Button onClick={()=>ctx.action(async()=>{await api('/conversations/'+c.id,'PATCH',{status:'active'});await detail.refresh();})}>重新咨询</Button>}</div><div className="messages"><div className="chat-system">咨询记录仅用于为你提供选购服务，请勿发送密码等敏感信息。</div>{c.messages.length===0&&<div className="chat-welcome"><span>你好，很高兴为你服务。</span><p>你准备将电脑用于什么场景？也可以告诉我预算和最关心的问题。</p></div>}{c.messages.map((m:Data)=><div key={m.id} className={'message '+((ctx.customer?m.role==='customer':m.role==='staff')?'mine':'theirs')}><span className="message-name">{m.role==='customer'?c.customer_name:'门店顾问'} · {time(m.created_at)}</span><div className="bubble">{m.content}{m.card?.product_id&&<a className="message-product" href={m.card.source} target="_blank" rel="noreferrer">{m.card.image_id&&<img src={'/api/knowledge/images/'+m.card.image_id} alt={m.card.name}/>}<b>{m.card.name}</b><small>产品信息以对应版本为准 <LinkOutlined/></small></a>}</div></div>)}<div ref={end}/></div><div className="composer">{!ctx.customer&&<div className="composer-tools"><Button size="small" type="text" icon={<RobotOutlined/>} onClick={()=>ai('suggest')}>建议回复</Button><Select placeholder="选择产品卡片" value={product||undefined} onChange={setProduct} options={ctx.products.map(p=>({value:p.id,label:p.name}))} style={{width:190}} size="small"/><Button size="small" disabled={!product||!owned} onClick={()=>send(product)}>发送产品卡</Button></div>}<TextArea value={text} onChange={e=>setText(e.target.value)} autoSize={{minRows:3,maxRows:6}} placeholder={ctx.customer?'说说你的需求，我们一起选合适的电脑…':owned?'输入回复，或采用右侧 AI 建议…':'认领会话后可回复客户'} disabled={(!ctx.customer&&!owned)||c.status==='closed'} maxLength={6000} onKeyDown={e=>{if(e.key==='Enter'&&(e.ctrlKey||e.metaKey)){e.preventDefault();void send();}}}/><div className="composer-footer"><small>{ctx.customer?'顾问离线时，请耐心等待回复。':'Ctrl + Enter 发送 · AI 建议需人工确认'}</small><Button type="primary" loading={sending} icon={<SendOutlined/>} disabled={!text.trim()||(!ctx.customer&&!owned)||c.status==='closed'} onClick={()=>send()}>发送</Button></div></div></section>
 {ctx.customer&&<ConsultationProducts products={ctx.products} messages={c.messages} disabled={c.status==='closed'} onAsk={name=>setText(current=>current.trim()?current+'\n我想了解 '+name+'。':'我想了解 '+name+'，能介绍一下吗？')}/>}
 {!ctx.customer&&<aside className="ai-panel"><div className="ai-panel-heading"><div><span className="ai-mark"><ThunderboltOutlined/></span><b>AI 服务助手</b></div><Tooltip title="重新分析最新对话"><Button type="text" icon={<ReloadOutlined/>} aria-label="刷新需求分析" loading={analyzing} onClick={()=>ai('analysis')}/></Tooltip></div><div className="ai-panel-scroll"><CustomerNeeds analysis={analysis} editable={owned&&c.status!=='closed'} updating={analyzing||(c.requirements_current===false&&!c.requires_analysis)} onEdit={(field,value)=>setEdit({field,value,locked:true})} onAdopt={setText}/>

 {suggestion&&suggestion.reply!==analysis.next_question?.text&&<div className="suggestion"><h3>建议回复</h3><p>{suggestion.reply||suggestion.notice}</p>{suggestion.reply&&<Button block onClick={()=>setText(suggestion.reply)} disabled={!owned||c.status==='closed'}>采用到输入框</Button>}{suggestion.recommendations?.map((r:Data)=><div key={r.product_id} className="recommendation"><b>{ctx.products.find(p=>p.id===r.product_id)?.name}</b><p>{r.reason}</p><small>需确认：{r.limitation}</small></div>)}</div>}
 <div className="ai-actions"><Button block type="primary" ghost icon={<EditOutlined/>} onClick={brief}>转为营销创作任务</Button><Button block icon={<ScheduleOutlined/>} disabled={!owned} onClick={()=>ctx.action(async()=>{await api('/followups/plan','POST',{conversation_id:c.id,days:[1,3,7]});ctx.modal.success({title:'跟进计划已建立',content:'将在1、3、7天后提醒，由客服确认后发送。'});})}>安排 1 / 3 / 7 天跟进</Button><Select value={c.stage} disabled={!owned} options={['新咨询','需求确认','产品比较','考虑中','已成交','暂不购买'].map(value=>({value,label:value}))} onChange={stage=>ctx.action(async()=>{await api('/conversations/'+c.id,'PATCH',{stage});await detail.refresh();})}/></div><Button type="text" block onClick={()=>ctx.modal.info({title:'客户咨询档案',width:680,content:<><Descriptions column={1} items={[{key:'n',label:'客户',children:c.customer_name},{key:'s',label:'阶段',children:c.stage},{key:'t',label:'创建时间',children:time(c.created_at)}]}/><p>{analysis.summary||'尚无需求摘要'}</p><p>本次咨询共 {c.messages.length} 条消息。</p></>})}>查看客户档案</Button></div></aside>}
 </div><Modal open={!!edit} title={edit?'修改'+NEED_FIELDS[edit.field]?.label:'修改需求'} footer={null} onCancel={()=>setEdit(null)}><p>{edit&&NEED_FIELDS[edit.field]?.hint}。只填写已确认的信息。</p><TextArea rows={4} value={edit?.value} onChange={e=>setEdit({...edit,value:e.target.value})}/><div className="modal-actions"><Button onClick={()=>ctx.action(async()=>{await api(`/conversations/${c.id}/analysis`,'PATCH',{...edit,locked:false});setEdit(null);await detail.refresh();})}>恢复自动更新</Button><Button type="primary" onClick={()=>ctx.action(async()=>{await api(`/conversations/${c.id}/analysis`,'PATCH',edit);setEdit(null);await detail.refresh();})}>保存修正</Button></div></Modal></>;
}

function Creator(ctx:Context&{initial:string}){
 const [form]=Form.useForm(),[busy,setBusy]=useState(false),[jobId,setJobId]=useState('');
 useEffect(()=>{if(ctx.initial){try{form.setFieldsValue(JSON.parse(ctx.initial));}catch{}}},[ctx.initial]);
 const submit=async(values:Data)=>{setBusy(true);const r=await ctx.action(()=>api('/marketing/tasks','POST',values));if(r){setJobId(r.job_id);ctx.watch(r.job_id,j=>ctx.navigate('works',j.result.work_id));}setBusy(false);};
 return <><Heading eyebrow="CONTENT STUDIO" title="营销创作" description=""/><div className="studio-grid studio-simple"><section className="panel studio-form"><div className="section-title"><h2>创作设置</h2></div><Form form={form} layout="vertical" onFinish={submit} initialValues={{platform:'小红书',goal:'引导咨询与到店体验',tone:'自然、专业、有温度'}}><Form.Item label="产品型号与版本" name="product_id" rules={[{required:true,message:'请选择具体产品型号'}]}><Select showSearch optionFilterProp="label" placeholder="选择产品，避免混淆系统与配置" options={ctx.products.map(p=>({value:p.id,label:p.name}))}/></Form.Item><Form.Item label="发布平台" name="platform" rules={[{required:true}]}><Select options={PLATFORMS.map(p=>({value:p,label:p}))}/></Form.Item><Form.Item label="目标人群" name="audience" rules={[{required:true,message:'请描述内容写给谁'}]}><Input placeholder="例如：准备开学购机的大学新生" maxLength={500}/></Form.Item><Form.Item label="具体使用场景" name="scene" rules={[{required:true,message:'请补充具体场景'}]}><TextArea rows={3} placeholder="例如：每天在教室和图书馆间移动，做文档、上网课，偶尔制作社团海报。" maxLength={1000}/></Form.Item><div className="form-two"><Form.Item label="购买阶段（可选）" name="buying_stage"><Select allowClear placeholder="未提供则记为待确认" options={['了解产品','比较选型','准备到店','准备购买','暂不购买'].map(value=>({value,label:value}))}/></Form.Item><Form.Item label="主要问题（可选）" name="user_problem"><Input placeholder="例如：携带负担、课堂软件支持" maxLength={1000}/></Form.Item></div><div className="form-two"><Form.Item label="内容目标" name="goal" rules={[{required:true}]}><Input/></Form.Item><Form.Item label="表达语气" name="tone"><Input/></Form.Item></div><Form.Item label="重点与补充要求" name="emphasis"><TextArea rows={2} placeholder="想强调的卖点、客户顾虑、需要避免的表达…" maxLength={1000}/></Form.Item><Button type="primary" htmlType="submit" size="large" block icon={<ThunderboltOutlined/>} loading={busy}>生成图文</Button></Form>{jobId&&<TaskProgress jobId={jobId} ctx={ctx}/>}</section></div></>;
}

function TaskProgress({jobId,ctx}:{jobId:string;ctx:Context}){const {data,error}=useData('/jobs/'+jobId,2500);return <div className="task-progress">{error?<Alert type="error" message={error}/>:data?<><Badge status={data.status}/><b>{jobLabel(data)}</b><TaskQuestions result={data.result}/>{['failed','waiting_remote'].includes(data.status)&&<Button onClick={()=>ctx.action(async()=>{const j=await api('/jobs/'+jobId+'/retry','POST');ctx.watch(j.job_id);})}>重试</Button>}{['running','queued'].includes(data.status)&&<Button size="small" onClick={()=>ctx.action(()=>api('/jobs/'+jobId+'/cancel','POST'))}>停止等待</Button>}</>:<Spin/>}</div>}

function Works(ctx:Context&{selected:string}){
 const list=useData('/works');const [id,setId]=useState(ctx.selected),[query,setQuery]=useState('');
 useEffect(()=>setId(ctx.selected),[ctx.selected]);
 return <><Heading eyebrow="YOUR CONTENT LIBRARY" title={id?'编辑作品':'营销内容'} description="" extra={<Button type="primary" icon={<PlusOutlined/>} onClick={()=>ctx.navigate('create')}>新建作品</Button>}/>{id?<><Button type="text" onClick={()=>{setId('');void list.refresh();}}>← 返回作品库</Button><WorkEditor key={id} {...ctx} id={id}/></>:<><div className="list-toolbar"><Input prefix={<SearchOutlined/>} placeholder="搜索作品标题或平台" value={query} onChange={e=>setQuery(e.target.value)} style={{maxWidth:340}}/><span className="muted">共 {list.data?.length||0} 个作品</span></div><div className="work-grid">{list.data?.filter((w:Data)=>(w.content.title+w.brief.platform).includes(query)).map((w:Data)=><button className="work-card" key={w.id} onClick={()=>setId(w.id)}><div className="work-cover">{w.content.images?.[0]&&<img src={'/api/knowledge/images/'+w.content.images[0].id} alt={w.content.product_name}/>}<Tag>{w.brief.platform}</Tag></div><div className="work-copy"><Badge status={w.report.status}/><h3>{w.content.title}</h3><p>{w.content.intro||w.content.body.slice(0,70)}</p><div><span>{time(w.updated_at)}</span><span><ArrowRightOutlined/></span></div></div></button>)}</div>{list.data?.length===0&&<div className="panel"><Empty description="从一个具体场景，创作第一份内容"/><Button type="primary" onClick={()=>ctx.navigate('create')}>开始创作</Button></div>}{list.error&&<Alert type="error" message={list.error}/>}</>}</>;
}

function WorkEditor(ctx:Context&{id:string}){
 const [reviewBusy,setReviewBusy]=useState(false),[reviewError,setReviewError]=useState('');
 const detail=useData('/works/'+ctx.id),assets=useData('/assets',10000);const [form]=Form.useForm(),[mode,setMode]=useState('preview'),[imageIds,setImageIds]=useState<string[]>([]),[background,setBackground]=useState(''),[ratio,setRatio]=useState('3:4'),[scene,setScene]=useState(''),[poster,setPoster]=useState(''),[imageJob,setImageJob]=useState(''),[dirty,setDirty]=useState(false),[evidenceOpen,setEvidenceOpen]=useState(false);
 useEffect(()=>{if(detail.data){form.setFieldsValue(detail.data.content);setImageIds((detail.data.content.images||[]).map((im:Data)=>im.id));setScene(detail.data.brief.scene);setDirty(false);}},[detail.data]);
 const w=detail.data;if(!w)return <Loading error={detail.error}/>;const c=w.content,canExport=['passed','manual_passed'].includes(w.report.status);
 const product=ctx.products.find(p=>p.id===w.brief.product_id);
 const save=()=>ctx.action(async()=>{if(reviewBusy)throw new Error('请等待当前检查或调整完成');await api('/works/'+w.id,'PATCH',{...form.getFieldsValue(),expected_version:w.version,image_ids:imageIds});await detail.refresh();});
 const runReview=(kind:'verify'|'repair')=>ctx.action(async()=>{
  if(dirty)throw new Error('请先保存修改，再检查或调整');
  if(reviewBusy)return;
  setReviewBusy(true);setReviewError('');
  try{const j=await api('/works/'+w.id+'/'+kind,'POST',{expected_version:w.version});
   ctx.watch(j.job_id,undefined,result=>{void detail.refresh().finally(()=>setReviewBusy(false));setReviewError(result.status==='failed'?result.error:result.status==='cancelled'?'任务已停止，原稿已保留。':'');});
  }catch(e){setReviewBusy(false);throw e;}
 });
 const approve=async(note:string)=>{
  if(dirty||reviewBusy)throw new Error('请先保存修改并等待当前任务结束');
  setReviewBusy(true);setReviewError('');
  try{await api('/works/'+w.id+'/approve','POST',{expected_version:w.version,note});await detail.refresh();}
  finally{setReviewBusy(false);}
 };
 const exportContent=(format:string,draft=false)=>ctx.action(async()=>{if(dirty)throw new Error('请先保存修改');const r=await fetch(`/api/works/${w.id}/export?format=${format}&draft=${draft}`);if(!r.ok){const e=await r.json();throw new Error(e.detail);}const url=URL.createObjectURL(await r.blob());const a=document.createElement('a');a.href=url;a.download=`知客作品-v${w.version}.${format}`;a.click();URL.revokeObjectURL(url);});
 const copy=()=>ctx.action(async()=>{if(dirty)throw new Error('请先保存修改，再复制当前版本');const response=await fetch(`/api/works/${w.id}/export?format=txt&draft=${!canExport}`);if(!response.ok){const error=await response.json();throw new Error(error.detail);}const text=await response.text();if(navigator.clipboard)await navigator.clipboard.writeText(text);else ctx.modal.info({title:'复制内容',width:700,content:<TextArea readOnly rows={14} value={text}/>});});
 return <div className="editor-layout"><section className="panel editor-main"><div className="editor-toolbar"><div className="filter-tabs">{[['preview','图文预览'],['edit','编辑内容']].map(([k,v])=><button key={k} disabled={reviewBusy} className={mode===k?'active':''} onClick={()=>setMode(k)}>{v}</button>)}</div><div><Tag>{w.brief.platform}</Tag><Badge status={dirty?'unchecked':w.report.status}/></div></div>{mode==='preview'?<article className="article"><div className="eyebrow">{w.brief.platform} · {c.product_name}</div><h1>{c.title}</h1><p className="article-intro">{c.intro}</p><ArticleBody content={c}/><p className="article-cta">{c.cta}</p><div>{c.tags?.map((t:string)=><Tag key={t}>{t}</Tag>)}</div></article>:<Form form={form} disabled={reviewBusy} layout="vertical" className="article-edit" onValuesChange={()=>setDirty(true)}><Form.Item name="title" label="标题"><Input maxLength={200}/></Form.Item><Form.Item name="intro" label="导语"><TextArea rows={3}/></Form.Item><Form.Item name="body" label="正文"><TextArea rows={20}/></Form.Item><Form.Item name="cta" label="行动引导"><TextArea rows={2}/></Form.Item><Form.Item name="tags" label="标签"><Select mode="tags"/></Form.Item><Form.Item name="pending" label="需要确认的产品信息"><Select mode="tags"/></Form.Item><Form.Item label="配图（仅限同型号）"><ImagePicker disabled={reviewBusy} productId={w.brief.product_id} choices={w.available_images} selected={imageIds} onChange={ids=>{setImageIds(ids);setDirty(true);}}/></Form.Item><Button type="primary" onClick={save}>保存修改</Button><span className="muted"></span></Form>}
 <div className="export-toolbar"><Button icon={<CopyOutlined/>} onClick={copy}>复制文本</Button><Button icon={<DownloadOutlined/>} onClick={()=>exportContent('md',!canExport)}>导出{canExport?'':'草稿'} Markdown</Button><Dropdown menu={{items:['txt','html','zip'].map(key=>({key,label:key.toUpperCase()})),onClick:({key})=>exportContent(key,!canExport)}}><Button>更多格式 <MoreOutlined/></Button></Dropdown><Button onClick={()=>{ctx.navigate('create',JSON.stringify({...w.brief}));}}>换场景或平台改写</Button><Button onClick={()=>setEvidenceOpen(true)}>查看创作依据</Button></div><Modal open={evidenceOpen} destroyOnClose title="创作依据与检查明细" width={900} footer={null} onCancel={()=>setEvidenceOpen(false)}><CompetitionEvidence work={w}/></Modal></section>
 <aside className="editor-side"><ContentReview work={w} dirty={dirty} busy={reviewBusy} error={reviewError} onCheck={()=>runReview('verify')} onRepair={()=>runReview('repair')} onApprove={approve}/>
 <section className="panel"><Collapse ghost items={[{key:'v',label:'修改记录',children:w.versions.map((v:Data)=><div className="version-item" key={v.id}><b>{time(v.created_at)}</b><Button type="link" size="small" onClick={()=>ctx.modal.info({title:v.content.title,width:760,content:<Markdown text={v.content.body}/>})}>查看内容</Button></div>)}]}/></section>
 <section className="panel image-studio"><h3><PictureOutlined/> 制作海报</h3><p className="muted">选择背景和尺寸，制作产品海报。</p><label>画布比例</label><Select value={ratio} onChange={setRatio} options={['1:1','3:4','16:9'].map(value=>({value,label:value}))}/><label>背景场景</label><TextArea rows={3} value={scene} onChange={e=>setScene(e.target.value)} maxLength={800}/><Button block icon={<ThunderboltOutlined/>} onClick={()=>ctx.modal.confirm({title:'生成一张场景背景',content:'生成一张背景将消耗图片额度。',okText:'生成一张',onOk:()=>ctx.action(async()=>{const j=await api('/images/tasks','POST',{scene,ratio,request_id:requestId()});setImageJob(j.job_id);ctx.watch(j.job_id,job=>{setBackground(job.result.asset_id);void assets.refresh();});})})}>生成背景</Button>{imageJob&&<TaskProgress jobId={imageJob} ctx={ctx}/>}<label>选择已有背景</label><Select value={background||undefined} allowClear onChange={v=>setBackground(v||'')} placeholder="不选则使用纯色底" options={assets.data?.filter((a:Data)=>a.kind==='generated_background').map((a:Data)=>({value:a.id,label:'AI背景 · '+time(a.created_at)}))}/>{background&&<img className="background-thumb" src={'/api/assets/'+background} alt="AI场景背景"/>}<Button type="primary" ghost block disabled={!imageIds.length||dirty} onClick={()=>ctx.action(async()=>{const r=await api('/works/'+w.id+'/compose','POST',{image_id:imageIds[0],background_id:background,ratio});setPoster(r.id);await assets.refresh();})}>生成海报</Button>{poster&&<><img className="poster-preview" src={'/api/assets/'+poster} alt="已合成海报"/><a href={'/api/assets/'+poster} download="知客海报.png"><Button block icon={<DownloadOutlined/>}>下载海报</Button></a></>}{assets.data?.filter((a:Data)=>a.kind==='composite'&&a.metadata_json.work_id===w.id).map((a:Data)=><a key={a.id} href={'/api/assets/'+a.id} download={`海报-v${a.metadata_json.work_version}.png`}>下载已保存海报 · {a.metadata_json.ratio}<br/></a>)}<small>{product?.name}</small></section></aside></div>;
}

function ImagePicker({productId,choices,selected,onChange,disabled=false}:{disabled?:boolean;productId:string;choices?:Data[];selected:string[];onChange:(ids:string[])=>void}){const {data}=useData('/products/'+productId);return <div className="image-picker">{(choices??data?.images??[]).map((im:Data)=><button type="button" key={im.id} disabled={disabled} className={selected.includes(im.id)?'picked':''} onClick={()=>onChange(selected.includes(im.id)?selected.filter(i=>i!==im.id):selected.length<6?[...selected,im.id]:selected)}><img src={'/api/knowledge/images/'+im.id} alt={im.description} loading="lazy"/>{selected.includes(im.id)&&<CheckCircleOutlined/>}</button>)}</div>}

function Products(ctx:Context){
 const [pid,setPid]=useState(''),[query,setQuery]=useState(''),[results,setResults]=useState<Data[]>([]),[doc,setDoc]=useState<Data|null>(null),[product,setProduct]=useState<Data|null>(null);
 const choose=(id:string)=>ctx.action(async()=>{setPid(id);setProduct(await api('/products/'+id));});
 const search=()=>ctx.action(async()=>setResults(await api('/knowledge/search?q='+encodeURIComponent(query)+'&product_id='+pid)));
 return <><Heading eyebrow="KNOWLEDGE, NOT GUESSWORK" title="产品资料" description=""/><div className="knowledge-search panel"><Input.Search size="large" placeholder="搜索型号、功能、兼容或场景，例如：屏幕、移动办公…" value={query} onChange={e=>setQuery(e.target.value)} onSearch={search} enterButton="检索资料"/></div>{results.length>0&&<section className="panel"><div className="section-title"><h2>资料检索结果</h2><Button type="text" onClick={()=>setResults([])}>收起</Button></div>{results.map(r=><button className="search-result" key={r.id} onClick={()=>ctx.action(async()=>setDoc(await api('/knowledge/documents/'+r.id)))}><b>{r.title}</b><p>{r.excerpt?.slice(0,180)}</p></button>)}</section>}
 <div className="section-title catalog-heading"><h2>重点 PC 产品 <span>{ctx.products.length}</span></h2><Tag>完整型号，明确版本</Tag></div><div className="product-grid">{ctx.products.map(p=><ProductCard key={p.id} p={p} onClick={()=>choose(p.id)}/>)}</div><Modal open={!!product} title={product?.name} width={1000} footer={null} onCancel={()=>setProduct(null)}><div className="product-detail"><div><Markdown text={product?.facts.body||''}/></div><aside><h3>产品图片 · {product?.images.length} 张</h3><div className="image-picker product-gallery">{product?.images.map((im:Data)=><a key={im.id} href={im.source||im.url} target="_blank" rel="noreferrer"><img src={'/api/knowledge/images/'+im.id} alt={im.description}/><small>{im.description}</small></a>)}</div><Button type="primary" block onClick={()=>{setProduct(null);ctx.navigate('create',JSON.stringify({product_id:pid}));}}>以此产品创建内容</Button><h3>相关资料</h3>{product?.documents.map((d:Data)=><Button type="link" key={d.id} onClick={()=>ctx.action(async()=>setDoc(await api('/knowledge/documents/'+d.id)))}>{d.title}</Button>)}{product?.prices.length>0&&<><h3>公开价格历史快照</h3><Alert type="warning" message="页面价不是当日成交价，优惠与库存需另行核验。"/>{product?.prices.slice(0,3).map((r:Data,n:number)=><Descriptions key={n} bordered column={1} size="small" items={Object.entries(r).filter(([,v])=>v).map(([label,value])=>({key:label,label,children:String(value)}))}/>)}</>}</aside></div></Modal><Modal open={!!doc} title={doc?.title} width={900} footer={null} onCancel={()=>setDoc(null)}><Markdown text={doc?.body||''}/></Modal></>;
}

function Followups(ctx:Context&{selected:string}){const {data,error,refresh}=useData('/followups',10000);const [filter,setFilter]=useState('pending'),[edit,setEdit]=useState<Data|null>(null);const opened=useRef('');
 useEffect(()=>{if(ctx.selected&&data&&opened.current!==ctx.selected){const item=data.find((f:Data)=>f.id===ctx.selected);if(item){setEdit(item);opened.current=ctx.selected;}}},[ctx.selected,data]);
 return <><Heading eyebrow="THE NEXT CONVERSATION" title="跟进计划" description=""/><div className="panel"><div className="list-toolbar"><div className="filter-tabs">{[['pending','待处理'],['completed','已完成'],['all','全部']].map(([k,v])=><button key={k} className={filter===k?'active':''} onClick={()=>setFilter(k)}>{v}</button>)}</div><span className="muted">北京时间 · 仅提醒，不自动发送</span></div>{data?<Table rowKey="id" dataSource={data.filter((f:Data)=>filter==='all'||f.status===filter)} pagination={{pageSize:10}} columns={[{title:'客户',dataIndex:'customer_name',render:(v:string,r:Data)=><Button type="link" onClick={()=>ctx.navigate('chat',r.conversation_id)}>{v}</Button>},{title:'跟进目的',dataIndex:'purpose'},{title:'计划时间',dataIndex:'due_at',render:(v:string,r:Data)=><><span>{time(v)}</span>{r.status==='pending'&&new Date(v)<new Date()&&<Tag color="red">已逾期</Tag>}</>},{title:'状态',dataIndex:'status',render:(v:string)=><Tag>{v==='pending'?'待处理':v==='completed'?'已完成':'已停止'}</Tag>},{title:'操作',render:(_:unknown,r:Data)=><Button onClick={()=>setEdit(r)}>查看与处理</Button>}]} scroll={{x:650}}/>:<Loading error={error}/>}</div><Modal open={!!edit} title="跟进事项" onCancel={()=>setEdit(null)} footer={null}><Form key={edit?.id} layout="vertical" initialValues={edit||{}} onFinish={values=>ctx.action(async()=>{const payload={...values,due_at:values.due_at?new Date(values.due_at).toISOString():edit?.due_at};await api('/followups/'+edit?.id,'PATCH',payload);setEdit(null);await refresh();})}><Form.Item name="purpose" label="目的"><Input/></Form.Item><Form.Item label="计划时间（北京时间）"><input className="date-input" type="datetime-local" value={edit?.due_at?new Date(new Date(edit.due_at).getTime()+8*3600000).toISOString().slice(0,16):''} onChange={e=>setEdit({...edit,due_at:e.target.value+'+08:00'})}/></Form.Item><Form.Item name="script" label="建议话术"><TextArea rows={4}/></Form.Item><Form.Item name="status" label="状态"><Select options={[{value:'pending',label:'待处理'},{value:'completed',label:'已完成'},{value:'cancelled',label:'停止跟进'}]}/></Form.Item><Form.Item name="feedback" label="本次反馈与结果"><TextArea rows={3}/></Form.Item><Button block type="primary" htmlType="submit">保存记录</Button></Form></Modal></>;
}

function Tasks(ctx:Context){
 const {data,error,refresh}=useData('/jobs',2500);const [filter,setFilter]=useState('all'),[detail,setDetail]=useState<Data|null>(null);
 const names:Data={analysis:'需求分析',suggest:'回复建议',generate:'营销创作',verify:'作品核验',image:'场景背景',import:'知识库导入'};
 const fields:Data={product_id:'产品型号',audience:'目标人群',scene:'使用场景',goal:'内容目标',platform:'发布平台',evidence_conflicts:'来源冲突（须人工核对）'};
 return <><Heading eyebrow="TASK HISTORY" title="通知与进度" description=""/><section className="panel"><div className="list-toolbar"><Select aria-label="筛选任务状态" value={filter} onChange={setFilter} options={[{value:'all',label:'全部任务'},{value:'active',label:'进行中'},{value:'attention',label:'需要处理'},{value:'completed',label:'已完成'}]}/><Button icon={<ReloadOutlined/>} onClick={()=>void refresh()}>刷新</Button></div>{error&&<Alert type="error" message={error}/>}<Table rowKey="id" dataSource={(data||[]).filter((j:Data)=>filter==='all'||(filter==='active'?['running','queued'].includes(j.status):filter==='attention'?['failed','waiting_remote','needs_input','cancelled'].includes(j.status):j.status===filter))} pagination={{pageSize:10}} scroll={{x:760}} columns={[{title:'任务',dataIndex:'kind',render:(kind:string)=>names[kind]||kind},{title:'状态',dataIndex:'status',render:(status:string)=><Badge status={status}/>},{title:'进度',render:(_:unknown,j:Data)=><><b>{jobLabel(j)}</b></>},{title:'时间',dataIndex:'created_at',render:(value:string)=>time(value)},{title:'操作',render:(_:unknown,j:Data)=><div className="task-actions"><Button size="small" onClick={()=>setDetail(j)}>详情</Button>{j.result?.work_id&&<Button size="small" onClick={()=>ctx.navigate('works',j.result.work_id)}>查看作品</Button>}{j.kind==='generate'&&j.status==='needs_input'&&<Button size="small" onClick={()=>ctx.navigate('create',JSON.stringify(j.payload))}>补充信息</Button>}{['failed','waiting_remote','cancelled'].includes(j.status)&&(j.kind!=='image'||j.remote_id)&&j.kind!=='import'&&<Button size="small" onClick={()=>ctx.action(async()=>{const r=await api('/jobs/'+j.id+'/retry','POST');ctx.watch(r.job_id);await refresh();})}>{j.kind==='image'?'继续查看':'重试'}</Button>}{['queued','running','waiting_remote'].includes(j.status)&&<Button size="small" onClick={()=>ctx.action(async()=>{await api('/jobs/'+j.id+'/cancel','POST');await refresh();})}>停止等待</Button>}</div>}]} /></section><Modal open={!!detail} title={names[detail?.kind]||'任务详情'} footer={null} onCancel={()=>setDetail(null)}><Badge status={detail?.status}/><p>{detail&&jobLabel(detail)}</p><TaskQuestions result={detail?.result}/>{detail?.result?.needs_input&&<Alert type="warning" message={'请补充：'+detail.result.needs_input.map((x:string)=>fields[x]||x).join('、')}/>}{detail?.kind==='image'&&!detail.remote_id&&detail.status==='failed'&&<p>背景生成未完成，请联系管理员检查图片服务。</p>}{detail?.kind==='suggest'&&detail.result?.reply&&<><h3>建议回复（未发送）</h3><p>{detail.result.reply}</p><Button onClick={()=>{setDetail(null);ctx.navigate('chat',detail.target_id);}}>打开对应会话</Button></>}{detail?.result?.asset_id&&<img style={{width:'100%'}} src={'/api/assets/'+detail.result.asset_id} alt="已生成背景"/>}</Modal></>;
}

function Settings(ctx:Context){
 const status=useData('/admin/status',15000),users=useData('/admin/users'),store=useData('/store'),jobs=useData('/jobs',5000),audit=useData('/admin/audit');const [add,setAdd]=useState(false),[password,setPassword]=useState(false);
 if(!status.data)return <Loading error={status.error}/>;const s=status.data;
 return <><Heading eyebrow="WORKSPACE SETTINGS" title="把工作台，准备好。" description="连接状态、产品知识和团队权限，在这里统一管理。"/><div className="settings-grid"><section className="panel"><h2>服务连接</h2><TextModelSettings onSaved={()=>void status.refresh()}/><div className="service-row"><div className="service-icon"><PictureOutlined/></div><div><b>魔搭背景生成</b><small>{s.image.model}</small></div><Tag color={s.image.configured?'green':'default'}>{s.image.configured?'已配置':'未配置'}</Tag></div><p className="muted">账号标记 NothingK；Token归属未通过身份接口确认。生成时才调用图像服务。</p>{s.image.last_error&&<Alert type="warning" message={s.image.last_error} showIcon/>}<Button onClick={()=>setPassword(true)}>修改我的登录密码</Button></section>
 <section className="panel"><h2>产品知识底座</h2><p>营销检索：{s.marketing_knowledge?.provider==='ima_first'?'ima 优先，失败时本地兜底':s.marketing_knowledge?.provider==='ima'?'仅 ima':'本地 ZIP'}</p>{s.marketing_knowledge?.configured&&<p className="muted">{s.marketing_knowledge.library_name} · {s.marketing_knowledge.connected?'最近检索成功':'等待检索或上次调用失败'}</p>}<Descriptions column={2} items={[{key:'v',label:'版本',children:s.knowledge.version},{key:'source',label:'来源',children:'本地 ZIP'},{key:'d',label:'文档',children:s.knowledge.documents},{key:'p',label:'产品',children:s.knowledge.products},{key:'i',label:'图片',children:s.knowledge.images},{key:'c',label:'校验文件',children:s.knowledge.checked_files}]}/><p className="muted">本地目录用于产品选择及回退；历史作品保留原来源。</p><Button icon={<ReloadOutlined/>} onClick={()=>ctx.action(async()=>{const j=await api('/admin/knowledge/reindex','POST');ctx.watch(j.job_id,()=>void status.refresh());})}>校验并重建索引</Button></section>
 <section className="panel"><div className="section-title"><h2>团队成员</h2><Button icon={<PlusOutlined/>} onClick={()=>setAdd(true)}>新增员工</Button></div>{users.data?.map((u:Data)=><div className="team-row" key={u.id}><span className="avatar pastel">{u.display_name[0]}</span><div><b>{u.display_name}</b><small>{u.username}</small></div><Select size="small" value={u.role} disabled={u.id===ctx.user.id} options={[{value:'staff',label:'客服'},{value:'admin',label:'管理员'}]} onChange={role=>ctx.action(async()=>{await api('/admin/users/'+u.id,'PATCH',{active:u.active,role});await users.refresh();})}/><Switch size="small" checked={u.active} disabled={u.id===ctx.user.id} onChange={active=>ctx.action(async()=>{await api('/admin/users/'+u.id,'PATCH',{active,role:u.role});await users.refresh();})}/></div>)}</section>
 <section className="panel"><h2>门店信息</h2>{store.data&&<Form layout="vertical" initialValues={store.data} onFinish={values=>ctx.action(()=>api('/admin/store','PUT',values))}><Form.Item name="name" label="门店名称"><Input/></Form.Item><Form.Item name="hours" label="接待时间"><Input/></Form.Item><Form.Item name="welcome" label="欢迎语"><TextArea rows={2}/></Form.Item><Button htmlType="submit">保存设置</Button></Form>}</section></div>
 <section className="panel"><div className="section-title"><h2>运行任务与恢复</h2><Button onClick={()=>ctx.action(async()=>{const r=await api('/admin/backup','POST');ctx.modal.success({title:'一致性备份已保存',content:r.filename});await status.refresh();})}>立即备份</Button></div><Button onClick={()=>ctx.action(async()=>{const r=await api('/admin/backup/drill','POST');ctx.modal.success({title:'恢复演练通过',content:`完整性：${r.integrity}；已在独立临时库恢复并验证，当前数据未改变。`});await status.refresh();})}>运行恢复演练</Button><p className="muted">最近备份：{s.backups?.slice(-1)[0]||'尚未手动备份'}；自动每日检查，保留最近7天。</p><Table size="small" rowKey="id" dataSource={jobs.data||[]} pagination={{pageSize:6}} columns={[{title:'任务',dataIndex:'kind'},{title:'状态',dataIndex:'status',render:(v:string)=><Badge status={v}/>},{title:'步骤',dataIndex:'step'},{title:'时间',dataIndex:'created_at',render:(v:string)=>time(v)},{title:'操作',render:(_:unknown,j:Data)=>['failed','waiting_remote','cancelled'].includes(j.status)?<Button size="small" onClick={()=>ctx.action(async()=>{const r=await api('/jobs/'+j.id+'/retry','POST');ctx.watch(r.job_id);})}>重试</Button>:null}]} scroll={{x:600}}/></section><section className="panel"><h2>操作记录</h2><div className="audit-list">{audit.data?.slice(0,12).map((a:Data)=><div key={a.id}><code>{a.action}</code><span>{time(a.created_at)}</span></div>)}</div></section>
 <Modal open={add} title="创建员工账号" footer={null} onCancel={()=>setAdd(false)} destroyOnClose><Form layout="vertical" onFinish={values=>ctx.action(async()=>{await api('/admin/users','POST',{...values,role:'staff'});setAdd(false);await users.refresh();})}><Form.Item name="display_name" label="姓名" rules={[{required:true}]}><Input/></Form.Item><Form.Item name="username" label="登录用户名" rules={[{required:true,pattern:/^[A-Za-z0-9_\-]{3,40}$/}]}><Input/></Form.Item><Form.Item name="password" label="初始密码（至少10位）" rules={[{required:true,min:10}]}><Input.Password/></Form.Item><Button block type="primary" htmlType="submit">创建客服</Button></Form></Modal><Modal open={password} title="修改密码" footer={null} onCancel={()=>setPassword(false)} destroyOnClose><Form layout="vertical" onFinish={values=>ctx.action(async()=>{await api('/auth/password','POST',values);location.reload();})}><Form.Item name="old_password" label="原密码" rules={[{required:true}]}><Input.Password/></Form.Item><Form.Item name="new_password" label="新密码" rules={[{required:true,min:10}]}><Input.Password/></Form.Item><Button block type="primary" htmlType="submit">修改并重新登录</Button></Form></Modal></>;
}

class ErrorBoundary extends React.Component<{children:React.ReactNode},{error:boolean}>{state={error:false};static getDerivedStateFromError(){return {error:true};}render(){return this.state.error?<div className="loading"><Alert type="error" message="页面加载遇到问题" description="数据已经保存在服务端，请刷新页面重试。"/><Button onClick={()=>location.reload()}>刷新页面</Button></div>:this.props.children;}}
createRoot(document.getElementById('root')!).render(<React.StrictMode><ConfigProvider locale={zhCN} theme={{token:{colorPrimary:'#b52f37',borderRadius:8,fontFamily:'Inter, "Microsoft YaHei", "PingFang SC", sans-serif',colorText:'#292d33',colorBgLayout:'#f6f6f3',fontSize:14,controlHeight:38}}}><AntApp><ErrorBoundary><Root/></ErrorBoundary></AntApp></ConfigProvider></React.StrictMode>);
